import { useMemo, useState, type FormEvent } from 'react'
import { ChartBar, ClipboardText, DownloadSimple, LockKey, Plus, UploadSimple, UserPlus } from '@phosphor-icons/react'
import { useApp } from '../app/context'
import { attendanceSummaryForGroup, gradeFor, reviewProgress, rosterForGroup, scheduleForDate, validateScore, weightedTotal } from '../domain/logic'
import type { Assessment, AssessmentCategory, AssessmentStatus, AttendanceStatus, BehaviorLog, Enrollment, FinalGrade, Room, ScheduleSlot, Student, SubmissionStatus, TeacherLeave, TeachingGroup } from '../domain/types'
import { makeMutation } from '../features/sync/engine'
import { exportExcel, exportPdf } from '../features/export/localExport'
import { Button, Dialog, Field, Input, Select, Textarea } from '../components/ui'
import { parseRosterRows, type RosterImportRow } from '../features/roster/excelRoster'

const attendanceStates: AttendanceStatus[] = ['PRESENT', 'LATE', 'ABSENT', 'LEAVE']
const submissionStates: SubmissionStatus[] = ['SUBMITTED', 'LATE', 'MISSING', 'EXEMPT']
const assessmentLabels: Record<AssessmentStatus, string> = { DRAFT: 'ร่าง', OPEN: 'เปิดรับงาน', DUE: 'ถึงกำหนดตรวจ', REVIEWING: 'กำลังตรวจ', REVIEWED: 'ตรวจครบ', ARCHIVED: 'เก็บถาวร' }

function PageHead({ title, body, children }: { title: string; body: string; children?: React.ReactNode }) { return <header className="page-head"><div><h1>{title}</h1><p>{body}</p></div>{children}</header> }
function fullName(student: { title: string; firstName: string; lastName: string }) { return `${student.title}${student.firstName} ${student.lastName}` }
function useGroupFilter() {
  const { data } = useApp(); const [gradeId, setGradeId] = useState(data.gradeLevels[0]?.id ?? '')
  const groups = data.teachingGroups.filter((item) => item.gradeLevelId === gradeId); const [groupId, setGroupId] = useState(groups[0]?.id ?? data.teachingGroups[0]?.id ?? '')
  const group = data.teachingGroups.find((item) => item.id === groupId && item.gradeLevelId === gradeId) ?? groups[0]
  return { gradeId, setGradeId: (id: string) => { setGradeId(id); setGroupId(data.teachingGroups.find((item) => item.gradeLevelId === id)?.id ?? '') }, groups, groupId: group?.id ?? '', setGroupId, group }
}
function GroupFilters({ filter }: { filter: ReturnType<typeof useGroupFilter> }) { const { data, t } = useApp(); return <div className="filters"><Field label={t('gradeLevel')}><Select value={filter.gradeId} onChange={(e) => filter.setGradeId(e.target.value)}>{data.gradeLevels.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field><Field label={t('room')}><Select value={filter.groupId} onChange={(e) => filter.setGroupId(e.target.value)}>{filter.groups.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field></div> }

function localDate() { const date = new Date(); date.setMinutes(date.getMinutes() - date.getTimezoneOffset()); return date.toISOString().slice(0,10) }
const weekdayNames = ['อาทิตย์','จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์']

export function TodayPage() {
  const { data, navigate, t } = useApp(); const today = new Date(); const date = localDate(); const weekday = today.getDay(); const slots = data.scheduleSlots.filter((item) => item.weekday === weekday).sort((a,b) => a.startTime.localeCompare(b.startTime)); const due = data.assessments.filter((item) => ['DUE','REVIEWING'].includes(item.status)); const missing = data.scores.filter((item) => item.value === null).length; const leave = (data.teacherLeaves ?? []).find((item) => item.date === date)
  return <><PageHead title={t('todayTitle')} body={t('todayBody')}><Button onClick={() => navigate('work')}><Plus />{t('createWork')}</Button></PageHead>{leave && <div className="banner warning"><div><strong>วันนี้บันทึกเป็นวันลา</strong><div className="meta"><span>{leave.reason}</span><span>ครูสอนแทน: {leave.substituteName}</span><span>{leave.substitutePhone}</span></div></div><Button variant="secondary" onClick={() => navigate('schedule')}>ดูรายละเอียด</Button></div>}<div className="summary-strip"><div className="summary-cell"><strong>{slots.length}</strong><span>คาบวันนี้</span></div><div className="summary-cell"><strong>{due.length}</strong><span>{t('dueForReview')}</span></div><div className="summary-cell"><strong>{missing}</strong><span>{t('missingScores')}</span></div><div className="summary-cell"><strong>{data.students.length}</strong><span>นักเรียนทั้งหมด</span></div></div><div className="split-grid"><section className="panel"><h2>{t('nextClass')}</h2><div className="list">{slots.length ? slots.map((slot) => { const group = data.teachingGroups.find((item) => item.id === slot.teachingGroupId); return <div className="list-row" key={slot.id}><div className="list-row-main"><strong>{group?.name}</strong><div className="meta"><span>คาบ {slot.period}</span><span>{slot.startTime}–{slot.endTime}</span></div></div><Button variant="secondary" onClick={() => navigate('attendance')}>{t('startAttendance')}</Button></div> }) : <div className="empty-state">วันนี้ไม่มีคาบสอน</div>}</div></section><section className="panel"><h2>{t('dueForReview')}</h2><div className="list">{due.slice(0,5).map((assessment) => <div className="list-row" key={assessment.id}><div className="list-row-main"><strong>{assessment.title}</strong><div className="meta"><span>{data.gradeLevels.find((item) => item.id === assessment.gradeLevelId)?.name}</span><span>{assessment.maxScore} คะแนน</span></div></div><Button variant="secondary" onClick={() => navigate('quick-edit')}>{t('continueReview')}</Button></div>)}</div></section></div></>
}

export function AttendancePage() {
  const { data, mutate, t } = useApp()
  const [date,setDate] = useState(localDate())
  const initialSchedule = scheduleForDate(data,date)
  const [groupId,setGroupId] = useState(initialSchedule.groups[0]?.id??'')
  const [period,setPeriod] = useState(()=>String(initialSchedule.slots.find((item)=>item.teachingGroupId===initialSchedule.groups[0]?.id)?.period??''))
  const daySchedule = scheduleForDate(data,date)
  const group = daySchedule.groups.find((item)=>item.id===groupId)??daySchedule.groups[0]
  const selectedGroupId = group?.id??''
  const groupSlots = daySchedule.slots.filter((item)=>item.teachingGroupId===selectedGroupId)
  const periodOptions=[...new Map(groupSlots.map((item)=>[item.period,item])).values()]
  const periodNumber = Number(period)
  const validPeriod = periodOptions.some((item)=>item.period===periodNumber)
  const roster = group ? rosterForGroup(data,group.id) : []
  const session = validPeriod ? data.attendanceSessions.find((item)=>item.teachingGroupId===selectedGroupId&&item.date===date&&item.period===periodNumber) : undefined
  const selectedSummary=attendanceSummaryForGroup(data,selectedGroupId)
  const roomSummaries=data.teachingGroups.map((item)=>({group:item,summary:attendanceSummaryForGroup(data,item.id)}))
  const changeDate=(value:string)=>{if(!value)return;const next=scheduleForDate(data,value);const nextGroupId=next.groups[0]?.id??'';setDate(value);setGroupId(nextGroupId);setPeriod(String(next.slots.find((item)=>item.teachingGroupId===nextGroupId)?.period??''))}
  const changeGroup=(value:string)=>{setGroupId(value);setPeriod(String(daySchedule.slots.find((item)=>item.teachingGroupId===value)?.period??''))}
  const startSession = async () => { if (!selectedGroupId||!validPeriod) return; const now = new Date().toISOString(); const sessionId = `session:${selectedGroupId}:${date}:${periodNumber}`; await mutate(makeMutation('AttendanceSession','attendance.session.upsert',{ session:{id:sessionId,version:1,createdAt:now,updatedAt:now,teachingGroupId:selectedGroupId,date,period:periodNumber}, records:roster.map((student)=>({id:`${sessionId}:${student.id}`,version:1,createdAt:now,updatedAt:now,sessionId,studentId:student.id,status:'PRESENT' as AttendanceStatus})) })) }
  const changeAttendance = (studentId:string) => { if(!session)return; const current=data.attendanceRecords.find((item)=>item.sessionId===session.id&&item.studentId===studentId); const status=attendanceStates[(attendanceStates.indexOf(current?.status??'PRESENT')+1)%attendanceStates.length]; void mutate(makeMutation('AttendanceRecord','attendance.update',{id:current?.id??`${session.id}:${studentId}`,sessionId:session.id,studentId,status},current?.version??0)) }
  const counts = attendanceStates.reduce<Record<AttendanceStatus,number>>((acc,status)=>{acc[status]=data.attendanceRecords.filter((item)=>item.sessionId===session?.id&&item.status===status).length;return acc},{PRESENT:0,LATE:0,ABSENT:0,LEAVE:0})
  const row=(student:typeof roster[number],mobile=false)=>{const status=data.attendanceRecords.find((item)=>item.sessionId===session?.id&&item.studentId===student.id)?.status??'PRESENT';const button=<button className={`state-button state-${status.toLowerCase()}`} onClick={()=>changeAttendance(student.id)}>{t(status==='PRESENT'?'present':status==='LATE'?'late':status==='ABSENT'?'absent':'leave')}</button>;return mobile?<article className="student-card" key={student.id}><div className="student-card-head"><div className="student-cell"><strong>{student.number}. {fullName(student)}</strong><span>{student.nickname} · {student.studentCode}</span></div>{button}</div></article>:<tr key={student.id}><td>{student.number}</td><td className="student-cell"><strong>{fullName(student)}</strong><span>{student.nickname} · {student.studentCode}</span></td><td>{button}</td></tr>}
  return <><PageHead title="เช็กชื่อและภาพรวมการมาเรียน" body="เลือกวันที่ ห้อง และคาบจากตารางสอนเพื่อเช็กชื่อ"/><section className="panel attendance-entry"><div className="section-head"><div><h2>เช็กชื่อรายคาบ</h2><p className="muted">ห้องและคาบจะเปลี่ยนตามวันที่และตารางสอนของปีการศึกษาที่กำลังดู</p></div><span className="status-badge">วัน{weekdayNames[daySchedule.weekday]} · {daySchedule.groups.length} ห้อง</span></div><div className="filters attendance-filters"><Field label="1. วันที่"><Input type="date" value={date} onChange={(e)=>changeDate(e.target.value)}/></Field><Field label="2. ห้องตามตารางสอน" helper={daySchedule.groups.length?'แสดงเฉพาะห้องที่มีสอนในวันที่เลือก':'ไม่มีห้องตามตารางในวันนี้'}><Select value={selectedGroupId} disabled={!daySchedule.groups.length} onChange={(e)=>changeGroup(e.target.value)}>{daySchedule.groups.length?daySchedule.groups.map((item)=><option key={item.id} value={item.id}>{item.name}</option>):<option value="">ไม่มีคาบสอน</option>}</Select></Field><Field label="3. คาบตามตารางสอน" helper="เลือกได้เฉพาะคาบของห้องนี้ในวันที่เลือก"><Select value={period} disabled={!periodOptions.length} onChange={(e)=>setPeriod(e.target.value)}>{periodOptions.length?periodOptions.map((slot)=><option key={slot.id} value={slot.period}>คาบ {slot.period} · {slot.startTime}–{slot.endTime}</option>):<option value="">ไม่มีคาบ</option>}</Select></Field></div>{!daySchedule.groups.length?<div className="empty-state"><div><h2>ไม่มีคาบสอนในวัน{weekdayNames[daySchedule.weekday]}</h2><p>เลือกวันที่อื่น หรือตั้งตารางสอนของห้องก่อนเริ่มเช็กชื่อ</p></div></div>:!validPeriod?<div className="empty-state"><div><h2>ไม่มีคาบในตารางสอนของห้องนี้</h2><p>กรุณาตรวจตารางสอนหรือเลือกห้องอื่น</p></div></div>:!session?<div className="empty-state"><div><h2>ยังไม่ได้เริ่มเช็กชื่อคาบ {periodNumber}</h2><p>นักเรียนทั้งห้องจะตั้งต้นเป็น “มา” แล้วแก้เฉพาะคนที่สาย ขาด หรือลา</p><Button onClick={()=>void startSession()}>เริ่มเช็กชื่อ {roster.length} คน</Button></div></div>:<><div className="summary-strip"><div className="summary-cell"><strong>{counts.PRESENT}</strong><span>มา</span></div><div className="summary-cell"><strong>{counts.LATE}</strong><span>สาย</span></div><div className="summary-cell"><strong>{counts.ABSENT}</strong><span>ขาด</span></div><div className="summary-cell"><strong>{counts.LEAVE}</strong><span>ลา</span></div></div><div className="table-wrap"><table className="data-table attendance-table"><thead><tr><th>{t('number')}</th><th>{t('student')}</th><th>{t('attendance')}</th></tr></thead><tbody>{roster.map((item)=>row(item))}</tbody></table></div><div className="mobile-roster">{roster.map((item)=>row(item,true))}</div></>}</section><section className="panel attendance-overview"><div className="section-head"><div><h2>ภาพรวมทุกห้อง</h2><p className="muted">เปอร์เซ็นต์ “มา” รวมผู้ที่มาสาย และคำนวณจากรายการเช็กชื่อจริง</p></div></div><div className="attendance-room-grid">{roomSummaries.map(({group:item,summary})=><article className={`metric-card ${item.id===selectedGroupId?'active':''}`} key={item.id}><strong>{item.name}</strong><div className="metric-value">{summary.presentPercent}%</div><span>มาเรียน · เช็กแล้ว {summary.days} วัน</span><div className="metric-split"><span>ขาด {summary.absentPercent}%</span><span>ลา {summary.leavePercent}%</span></div></article>)}</div></section>{selectedGroupId&&<section className="panel attendance-insight"><div className="summary-strip"><div className="summary-cell"><strong>{selectedSummary.days}</strong><span>วันที่เช็กชื่อ</span></div><div className="summary-cell"><strong>{selectedSummary.presentPercent}%</strong><span>มาเรียน</span></div><div className="summary-cell"><strong>{selectedSummary.absentPercent}%</strong><span>ขาดเรียน</span></div><div className="summary-cell"><strong>{selectedSummary.leavePercent}%</strong><span>ลา</span></div></div><h3>นักเรียนที่ขาดบ่อยในห้องนี้</h3>{selectedSummary.frequentAbsences.length?<div className="risk-list">{selectedSummary.frequentAbsences.map(({student,absent,percent})=><div className="risk-row" key={student.id}><div className="student-cell"><strong>{student.number}. {fullName(student)}</strong><span>{student.nickname} · {student.studentCode}</span></div><div><strong>{absent} ครั้ง</strong><span className="muted"> · {percent}%</span></div></div>)}</div>:<p className="muted">ยังไม่พบประวัติขาดเรียน</p>}</section>}</>
}

export function QuickEditPage() {
  const { data, mutate, t } = useApp(); const filter = useGroupFilter(); const roster = filter.group ? rosterForGroup(data, filter.group.id) : []
  const targeted = data.assessmentTargets.filter((item) => item.teachingGroupId === filter.groupId).map((target) => data.assessments.find((item) => item.id === target.assessmentId)).filter(Boolean) as Assessment[]
  const [assessmentId, setAssessmentId] = useState(targeted[0]?.id ?? ''); const assessment = targeted.find((item) => item.id === assessmentId) ?? targeted[0]
  const changeSubmission = (studentId: string) => { if (!assessment) return; const current = data.submissions.find((item) => item.assessmentId === assessment.id && item.studentId === studentId); const status = submissionStates[(submissionStates.indexOf(current?.status ?? 'MISSING') + 1) % submissionStates.length]; void mutate(makeMutation('Submission','submission.update',{ id: current?.id ?? `${assessment.id}:${studentId}`, assessmentId: assessment.id, studentId, status, submittedAt: ['SUBMITTED','LATE'].includes(status) ? new Date().toISOString() : undefined }, current?.version ?? 0)) }
  const saveScore = (studentId: string, raw: string) => { if (!assessment) return; const value = raw === '' ? null : Number(raw); if (validateScore(value, assessment.maxScore)) return; const current = data.scores.find((item) => item.assessmentId === assessment.id && item.studentId === studentId); void mutate(makeMutation('Score','score.update',{ id: current?.id ?? `${assessment.id}:${studentId}`, assessmentId: assessment.id, studentId, value }, current?.version ?? 0)) }
  const row = (student: typeof roster[number], mobile = false) => { const submission = data.submissions.find((item) => item.assessmentId === assessment?.id && item.studentId === student.id)?.status ?? 'MISSING'; const score = data.scores.find((item) => item.assessmentId === assessment?.id && item.studentId === student.id)?.value; const statusButton=<button className={`state-button state-${submission.toLowerCase()}`} onClick={() => changeSubmission(student.id)} disabled={!assessment}>{t(submission === 'SUBMITTED' ? 'submitted' : submission === 'LATE' ? 'submittedLate' : submission === 'MISSING' ? 'missing' : 'exempt')}</button>; const scoreInput=<input className="score-input" type="number" inputMode="decimal" min="0" max={assessment?.maxScore} defaultValue={score ?? ''} aria-label={`คะแนน ${fullName(student)}`} onBlur={(e) => saveScore(student.id, e.target.value)} disabled={!assessment} />; return mobile ? <article className="student-card" key={student.id}><div className="student-card-head"><div className="student-cell"><strong>{student.number}. {fullName(student)}</strong><span>{student.nickname} · {student.studentCode}</span></div></div><div className="student-card-actions work-actions">{statusButton}<label className="score-label">คะแนน {scoreInput} / {assessment?.maxScore ?? '—'}</label></div></article> : <tr key={student.id}><td>{student.number}</td><td className="student-cell"><strong>{fullName(student)}</strong><span>{student.nickname} · {student.studentCode}</span></td><td>{statusButton}</td><td>{scoreInput} / {assessment?.maxScore ?? '—'}</td></tr> }
  return <><PageHead title={t('quickEditTitle')} body={t('quickEditBody')} /><GroupFilters filter={filter} /><div className="filters item-filter"><Field label={t('item')}><Select value={assessment?.id ?? ''} onChange={(e) => setAssessmentId(e.target.value)}>{targeted.map((item) => <option key={item.id} value={item.id}>{item.title} · {assessmentLabels[item.status]}</option>)}</Select></Field></div><div className="summary-strip"><div className="summary-cell"><strong>{roster.length}</strong><span>นักเรียน</span></div><div className="summary-cell"><strong>{assessment?.maxScore ?? '—'}</strong><span>{t('maxScore')}</span></div><div className="summary-cell"><strong>{assessment ? reviewProgress(assessment, filter.group!, data.enrollments, data.submissions, data.scores).reviewed : 0}</strong><span>ตรวจแล้ว</span></div><div className="summary-cell"><strong>{assessment ? roster.length-reviewProgress(assessment, filter.group!, data.enrollments, data.submissions, data.scores).reviewed : 0}</strong><span>รอตรวจ</span></div></div>{assessment?<><div className="table-wrap"><table className="data-table"><thead><tr><th>{t('number')}</th><th>{t('student')}</th><th>{t('submission')}</th><th>{t('score')}</th></tr></thead><tbody>{roster.map((item) => row(item))}</tbody></table></div><div className="mobile-roster">{roster.map((item) => row(item, true))}</div></>:<div className="empty-state">ห้องนี้ยังไม่มีงาน กรุณาสร้างงานและเลือกห้องนี้ก่อน</div>}</>
}

export function WorkPage() {
  const { data, mutate, navigate, t } = useApp()
  const [dialog, setDialog] = useState(false)
  const [targetError,setTargetError]=useState('')
  const create = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const form = new FormData(event.currentTarget); const targets = form.getAll('targets').map(String)
    if (!targets.length) { setTargetError('เลือกอย่างน้อย 1 ห้องสำหรับงานนี้'); return }
    const now = new Date().toISOString(); const assessment: Assessment = { id: crypto.randomUUID(), version: 1, createdAt: now, updatedAt: now, termId: data.terms.find((item) => item.active)?.id ?? data.terms[0].id, gradeLevelId: data.teachingGroups.find((item) => item.id === targets[0])?.gradeLevelId ?? data.gradeLevels[0].id, subjectId: data.subjects[0].id, categoryId: String(form.get('category')), title: String(form.get('title')), type: String(form.get('type')) as Assessment['type'], status: 'OPEN', assignedAt: String(form.get('assignedAt')), dueAt: String(form.get('dueAt')), maxScore: Number(form.get('maxScore')), instructions: String(form.get('instructions') ?? '') }
    await mutate(makeMutation('Assessment','assessment.create',{ assessment, targets: targets.map((groupId) => ({ id: crypto.randomUUID(), version: 1, createdAt: now, updatedAt: now, assessmentId: assessment.id, teachingGroupId: groupId })) })); setTargetError(''); setDialog(false)
  }
  return <><PageHead title={t('workTitle')} body={t('workBody')}><Button onClick={() => {setTargetError('');setDialog(true)}}><Plus />{t('createNewWork')}</Button></PageHead><div className="list">{[...data.assessments].sort((a,b) => b.dueAt.localeCompare(a.dueAt)).map((assessment) => { const groups = data.assessmentTargets.filter((item) => item.assessmentId === assessment.id).map((item) => data.teachingGroups.find((group) => group.id === item.teachingGroupId)).filter(Boolean) as TeachingGroup[]; const progress = groups.reduce((sum, group) => { const value = reviewProgress(assessment, group, data.enrollments, data.submissions, data.scores); return { reviewed: sum.reviewed + value.reviewed, total: sum.total + value.total } }, { reviewed: 0, total: 0 }); return <article className="list-row" key={assessment.id}><div className="list-row-main grow"><div className="button-row"><strong>{assessment.title}</strong><span className="status-badge">{assessmentLabels[assessment.status]}</span></div><div className="meta"><span>{data.gradeLevels.find((item) => item.id === assessment.gradeLevelId)?.name}</span><span>{groups.map((item) => item.name.split(' ').at(-1)).join(', ')}</span><span>ส่ง {assessment.dueAt}</span><span>{assessment.maxScore} คะแนน</span></div><div className="progress"><span style={{ width: `${progress.total ? progress.reviewed / progress.total * 100 : 0}%` }} /></div><small className="muted">ตรวจแล้ว {progress.reviewed}/{progress.total}</small></div><Button variant="secondary" onClick={() => navigate('quick-edit')}><ClipboardText />{t('startReview')}</Button></article> })}</div>{dialog && <Dialog title={t('createNewWork')} onClose={() => setDialog(false)}><form className="stack" onSubmit={create}><Field label={t('workName')}><Input name="title" required autoFocus /></Field><div className="field-row"><Field label={t('workType')}><Select name="type"><option value="ASSIGNMENT">การบ้าน</option><option value="WORK">ชิ้นงาน</option><option value="QUIZ">แบบทดสอบ</option><option value="MIDTERM">กลางภาค</option><option value="FINAL">ปลายภาค</option></Select></Field><Field label={t('maxScore')}><Input name="maxScore" type="number" min="1" step="0.5" defaultValue="10" required /></Field></div><div className="field-row"><Field label={t('assignedDate')}><Input name="assignedAt" type="date" defaultValue={new Date().toISOString().slice(0,10)} required /></Field><Field label={t('dueDate')}><Input name="dueAt" type="date" required /></Field></div><Field label="หมวดคะแนน"><Select name="category">{data.assessmentCategories.map((item) => <option key={item.id} value={item.id}>{item.name} ({item.weight}%)</option>)}</Select></Field><fieldset className="target-grid" aria-describedby={targetError?'target-error':undefined}><legend>{t('targetRooms')} <span className="helper">(เลือกได้ตั้งแต่ 1 ห้องขึ้นไป)</span></legend>{data.teachingGroups.map((item) => <label className="checkbox-row" key={item.id}><input type="checkbox" name="targets" value={item.id} onChange={()=>setTargetError('')} />{item.name}</label>)}</fieldset>{targetError&&<div id="target-error" className="error-copy" role="alert">{targetError}</div>}<Field label={t('instructions')}><Textarea name="instructions" /></Field><div className="button-row end"><Button type="button" variant="ghost" onClick={() => setDialog(false)}>{t('cancel')}</Button><Button type="submit">{t('createAndOpen')}</Button></div></form></Dialog>}</>
}

export function SchedulePage() {
  const { data, mutate } = useApp(); const [date,setDate]=useState(localDate()); const [dialog,setDialog]=useState(false); const weekday=new Date(`${date}T12:00:00`).getDay(); const daySlots=data.scheduleSlots.filter((item)=>item.weekday===weekday).sort((a,b)=>a.period-b.period); const leave=(data.teacherLeaves??[]).find((item)=>item.date===date); const allLeaves=[...(data.teacherLeaves??[])].sort((a,b)=>b.date.localeCompare(a.date))
  const saveLeave=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const form=new FormData(event.currentTarget);const now=new Date().toISOString();const record:TeacherLeave={id:leave?.id??`leave:${date}`,version:leave?.version??0,createdAt:leave?.createdAt??now,updatedAt:now,date,substituteName:String(form.get('substituteName')).trim(),substitutePhone:String(form.get('substitutePhone')).trim(),reason:String(form.get('reason')).trim(),note:String(form.get('note')??'').trim()};await mutate(makeMutation('TeacherLeave',leave?'teacherLeave.update':'teacherLeave.create',record,leave?.version??0));setDialog(false)}
  return <><PageHead title="ตารางสอนและวันลา" body="ดูตารางสอนรายวัน ประจำสัปดาห์ และประวัติวันลาทั้งหมด"><Button variant="secondary" onClick={()=>setDialog(true)}>{leave?'แก้ไขวันลา':'บันทึกวันลา'}</Button></PageHead><div className="filters item-filter"><Field label="วันที่ต้องการดู"><Input type="date" value={date} onChange={(e)=>setDate(e.target.value)}/></Field></div><div className="summary-strip"><div className="summary-cell"><strong>{weekdayNames[weekday]}</strong><span>วัน</span></div><div className="summary-cell"><strong>{daySlots.length}</strong><span>คาบสอน</span></div><div className="summary-cell"><strong>{daySlots.map((item)=>item.period).join(', ')||'—'}</strong><span>คาบที่</span></div><div className="summary-cell"><strong>{leave?'ลา':'สอนตามปกติ'}</strong><span>สถานะ</span></div></div>{leave&&<section className="panel leave-card"><h2>ข้อมูลวันลาของวันที่เลือก</h2><div className="leave-details"><div><span>สาเหตุ</span><strong>{leave.reason}</strong></div><div><span>ครูสอนแทน</span><strong>{leave.substituteName}</strong></div><div><span>เบอร์โทร</span><strong><a href={`tel:${leave.substitutePhone}`}>{leave.substitutePhone}</a></strong></div>{leave.note&&<div><span>หมายเหตุ</span><strong>{leave.note}</strong></div>}</div></section>}<section className="panel schedule-panel"><h2>คาบสอนวัน{weekdayNames[weekday]}</h2>{daySlots.length?<div className="schedule-list">{daySlots.map((slot)=>{const group=data.teachingGroups.find((item)=>item.id===slot.teachingGroupId);const room=data.rooms.find((item)=>item.id===group?.roomId);return <article className="schedule-row" key={slot.id}><div className="period-badge">{slot.period}</div><div className="grow"><strong>{group?.name}</strong><div className="meta"><span>{room?.name}</span><span>{slot.startTime}–{slot.endTime}</span></div></div>{leave&&<span className="status-badge warning">{leave.substituteName} สอนแทน</span>}</article>})}</div>:<div className="empty-state">ไม่มีคาบสอนในวันนี้</div>}</section><section className="panel leave-history"><div className="section-head"><div><h2>วันลาทั้งหมด</h2><p className="muted">รวมทั้งวันลาที่ผ่านมาและวันลาล่วงหน้า</p></div><span className="status-badge">{allLeaves.length} วัน</span></div>{allLeaves.length?<div className="leave-history-list">{allLeaves.map((item)=>{const day=new Date(`${item.date}T12:00:00`).getDay();const slots=data.scheduleSlots.filter((slot)=>slot.weekday===day).sort((a,b)=>a.period-b.period);return <article className="leave-history-row" key={item.id}><button type="button" className="date-button" onClick={()=>setDate(item.date)}><strong>{new Date(`${item.date}T12:00:00`).toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'})}</strong><span>วัน{weekdayNames[day]}</span></button><div className="grow"><strong>{item.reason}</strong><div className="meta"><span>ครูสอนแทน: {item.substituteName}</span><span><a href={`tel:${item.substitutePhone}`}>{item.substitutePhone}</a></span><span>{slots.length} คาบ · {slots.map((slot)=>`คาบ ${slot.period}`).join(', ')||'ไม่มีคาบ'}</span></div>{item.note&&<small className="muted">{item.note}</small>}</div></article>})}</div>:<div className="empty-state">ยังไม่มีข้อมูลวันลา</div>}</section><section className="panel weekly-overview"><h2>ตารางสอนประจำสัปดาห์</h2><div className="week-grid">{[1,2,3,4,5].map((day)=><div className="week-day" key={day}><h3>{weekdayNames[day]}</h3>{data.scheduleSlots.filter((item)=>item.weekday===day).sort((a,b)=>a.period-b.period).map((slot)=>{const group=data.teachingGroups.find((item)=>item.id===slot.teachingGroupId);return <div className="week-slot" key={slot.id}><strong>คาบ {slot.period}</strong><span>{group?.name}</span><small>{slot.startTime}–{slot.endTime}</small></div>})}</div>)}</div></section>{dialog&&<Dialog title={leave?'แก้ไขข้อมูลวันลา':'บันทึกวันลา'} onClose={()=>setDialog(false)}><form className="stack" onSubmit={saveLeave}><div className="banner"><div><strong>{date}</strong><div className="meta"><span>วัน{weekdayNames[weekday]}</span><span>{daySlots.length} คาบ</span><span>{daySlots.map((item)=>`คาบ ${item.period}`).join(', ')||'ไม่มีคาบสอน'}</span></div></div></div><Field label="สาเหตุการลา"><Textarea name="reason" defaultValue={leave?.reason} required autoFocus/></Field><Field label="ชื่อครูที่สอนแทน"><Input name="substituteName" defaultValue={leave?.substituteName} required/></Field><Field label="เบอร์โทรครูที่สอนแทน"><Input name="substitutePhone" type="tel" defaultValue={leave?.substitutePhone} required/></Field><Field label="หมายเหตุเพิ่มเติม"><Textarea name="note" defaultValue={leave?.note}/></Field><div className="button-row end"><Button type="button" variant="ghost" onClick={()=>setDialog(false)}>ยกเลิก</Button><Button type="submit">บันทึกวันลา</Button></div></form></Dialog>}</>
}

function CategoryManager({onClose}:{onClose:()=>void}) {
  const {data,mutate}=useApp(); const termId=data.terms.find((item)=>item.active)?.id??data.terms[0]?.id??''
  const [rows,setRows]=useState<AssessmentCategory[]>(()=>data.assessmentCategories.map((item)=>({...item}))); const [error,setError]=useState(''); const [busy,setBusy]=useState(false)
  const total=rows.reduce((sum,item)=>sum+Number(item.weight||0),0); const usedIds=new Set(data.assessments.map((item)=>item.categoryId))
  const add=()=>{const now=new Date().toISOString();setRows((items)=>[...items,{id:crypto.randomUUID(),version:0,createdAt:now,updatedAt:now,termId,name:'หมวดใหม่',weight:0}])}
  const update=(id:string,field:'name'|'weight',value:string)=>setRows((items)=>items.map((item)=>item.id===id?{...item,[field]:field==='weight'?Number(value):value}:item))
  const remove=(id:string)=>{if(usedIds.has(id))return;setRows((items)=>items.filter((item)=>item.id!==id));setError('')}
  const save=async()=>{const invalidName=rows.some((item)=>!item.name.trim());if(!rows.length){setError('ต้องมีอย่างน้อย 1 หมวดคะแนน');return}if(invalidName){setError('กรุณาใส่ชื่อหมวดคะแนนให้ครบ');return}if(rows.some((item)=>!Number.isFinite(item.weight)||item.weight<=0||item.weight>100)){setError('เปอร์เซ็นต์แต่ละหมวดต้องมากกว่า 0 และไม่เกิน 100');return}if(Math.abs(total-100)>0.001){setError(`เปอร์เซ็นต์รวมต้องเท่ากับ 100% (ขณะนี้ ${total}%)`);return}const activeIds=new Set(rows.map((item)=>item.id));const deletedIds=data.assessmentCategories.filter((item)=>!activeIds.has(item.id)).map((item)=>item.id);setBusy(true);try{await mutate(makeMutation('AssessmentCategory','assessmentCategories.replace',{records:rows.map((item)=>({...item,name:item.name.trim()})),deletedIds}));onClose()}catch(cause){setError(cause instanceof Error?cause.message:'บันทึกหมวดคะแนนไม่สำเร็จ')}finally{setBusy(false)}}
  return <Dialog title="จัดการหมวดและเปอร์เซ็นต์คะแนน" onClose={onClose}><div className="stack"><p className="muted">กำหนดน้ำหนักที่ใช้คำนวณคะแนนรวม ทุกหมวดรวมกันต้องเท่ากับ 100%</p><div className="category-list">{rows.map((item)=><div className="category-row" key={item.id}><Input aria-label={`ชื่อหมวด ${item.name}`} value={item.name} onChange={(e)=>update(item.id,'name',e.target.value)}/><label className="weight-input"><span className="sr-only">เปอร์เซ็นต์ {item.name}</span><Input type="number" inputMode="decimal" min="0.1" max="100" step="0.1" value={item.weight} onChange={(e)=>update(item.id,'weight',e.target.value)}/><strong>%</strong></label><Button type="button" variant="danger" disabled={usedIds.has(item.id)} title={usedIds.has(item.id)?'หมวดนี้มีงานใช้งานอยู่':'ลบหมวด'} onClick={()=>remove(item.id)}>ลบ</Button></div>)}</div><Button type="button" variant="secondary" onClick={add}><Plus/>เพิ่มหมวด</Button><div className={`category-total ${Math.abs(total-100)<0.001?'valid':'invalid'}`}><span>รวมทั้งหมด</span><strong>{total}%</strong></div>{error&&<div className="error-copy" role="alert">{error}</div>}<p className="helper">ปุ่มลบจะถูกปิดไว้สำหรับหมวดที่มีงานหรือข้อสอบใช้งานอยู่</p><div className="button-row end"><Button type="button" variant="ghost" onClick={onClose}>ยกเลิก</Button><Button type="button" onClick={()=>void save()} disabled={busy}>{busy?'กำลังบันทึก…':'บันทึกเปอร์เซ็นต์'}</Button></div></div></Dialog>
}

function RosterManager({onClose}:{onClose:()=>void}) {
  const {data,mutate}=useApp(); const [mode,setMode]=useState<'room'|'import'>('import'); const [groupId,setGroupId]=useState(data.teachingGroups[0]?.id??''); const [preview,setPreview]=useState<RosterImportRow[]>([]); const [fileName,setFileName]=useState(''); const [error,setError]=useState(''); const [message,setMessage]=useState(''); const [busy,setBusy]=useState(false)
  const downloadTemplate=async()=>{setError('');try{const ExcelJS=await import('exceljs');const workbook=new ExcelJS.Workbook();const sheet=workbook.addWorksheet('รายชื่อนักเรียน');sheet.columns=[{header:'รหัสนักเรียน',key:'studentCode',width:18},{header:'เลขที่',key:'number',width:10},{header:'คำนำหน้า',key:'title',width:14},{header:'ชื่อ',key:'firstName',width:20},{header:'นามสกุล',key:'lastName',width:22},{header:'ชื่อเล่น',key:'nickname',width:16},{header:'หมายเหตุ',key:'privateNote',width:28}];sheet.addRow({studentCode:'65001',number:1,title:'นาย',firstName:'ตัวอย่าง',lastName:'นักเรียน',nickname:'ตัวอย่าง',privateNote:''});sheet.getRow(1).eachCell((cell)=>{cell.font={bold:true,color:{argb:'FFFFFFFF'}};cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF166B59'}}});sheet.getColumn('studentCode').numFmt='@';sheet.views=[{state:'frozen',ySplit:1}];const buffer=await workbook.xlsx.writeBuffer();const blob=new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='KruNote-template-students.xlsx';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(cause){setError(cause instanceof Error?cause.message:'สร้างไฟล์ตัวอย่างไม่สำเร็จ')}}
  const readFile=async(file?:File)=>{setPreview([]);setMessage('');setError('');setFileName(file?.name??'');if(!file)return;if(!file.name.toLowerCase().endsWith('.xlsx')){setError('รองรับเฉพาะไฟล์ Excel .xlsx');return}setBusy(true);try{const ExcelJS=await import('exceljs');const workbook=new ExcelJS.Workbook();await workbook.xlsx.load(await file.arrayBuffer());const sheet=workbook.worksheets[0];if(!sheet)throw new Error('ไม่พบชีตในไฟล์ Excel');const rows:unknown[][]=[];sheet.eachRow({includeEmpty:false},(row)=>{const values:unknown[]=[];for(let column=1;column<=Math.max(sheet.columnCount,7);column++)values.push(row.getCell(column).text.trim());rows.push(values)});setPreview(parseRosterRows(rows))}catch(cause){setError(cause instanceof Error?cause.message:'อ่านไฟล์ Excel ไม่สำเร็จ')}finally{setBusy(false)}}
  const importStudents=async()=>{if(!groupId){setError('กรุณาเลือกห้องปลายทาง');return}if(!preview.length){setError('กรุณาเลือกไฟล์และตรวจตัวอย่างก่อนนำเข้า');return}const now=new Date().toISOString();const students:Student[]=preview.map((row)=>{const current=data.students.find((item)=>item.studentCode===row.studentCode);return{id:current?.id??crypto.randomUUID(),version:current?.version??0,createdAt:current?.createdAt??now,updatedAt:now,studentCode:row.studentCode,number:row.number,title:row.title,firstName:row.firstName,lastName:row.lastName,nickname:row.nickname,active:true,privateNote:row.privateNote}});const enrollments:Enrollment[]=students.map((student)=>{const current=data.enrollments.find((item)=>item.teachingGroupId===groupId&&item.studentId===student.id);return{id:current?.id??crypto.randomUUID(),version:current?.version??0,createdAt:current?.createdAt??now,updatedAt:now,teachingGroupId:groupId,studentId:student.id}});setBusy(true);setError('');try{await mutate(makeMutation('Student','students.import',{students,enrollments}));setMessage(`นำเข้าแล้ว ${students.length} คน · อัปเดตข้อมูลเดิม ${students.filter((item)=>data.students.some((current)=>current.id===item.id)).length} คน`);setPreview([]);setFileName('')}catch(cause){setError(cause instanceof Error?cause.message:'นำเข้ารายชื่อไม่สำเร็จ')}finally{setBusy(false)}}
  const createRoom=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const form=new FormData(event.currentTarget);const gradeLevelId=String(form.get('gradeLevelId'));const code=String(form.get('code')).trim();const name=String(form.get('name')).trim();if(data.rooms.some((item)=>item.gradeLevelId===gradeLevelId&&item.code.toLowerCase()===code.toLowerCase())){setError('มีรหัสห้องนี้ในระดับชั้นแล้ว');return}const term=data.terms.find((item)=>item.active)??data.terms[0];const subject=data.subjects[0];if(!term||!subject){setError('ไม่พบภาคเรียนหรือวิชาที่ใช้งาน');return}const now=new Date().toISOString();const roomId=crypto.randomUUID();const groupIdNew=crypto.randomUUID();const room:Room={id:roomId,version:0,createdAt:now,updatedAt:now,gradeLevelId,code,name};const group:TeachingGroup={id:groupIdNew,version:0,createdAt:now,updatedAt:now,termId:term.id,gradeLevelId,roomId,subjectId:subject.id,name:`${subject.name} ${name}`};const scheduleSlot:ScheduleSlot={id:crypto.randomUUID(),version:0,createdAt:now,updatedAt:now,teachingGroupId:groupIdNew,weekday:Number(form.get('weekday')),period:Number(form.get('period')),startTime:String(form.get('startTime')),endTime:String(form.get('endTime'))};if(scheduleSlot.startTime>=scheduleSlot.endTime){setError('เวลาเริ่มต้องมาก่อนเวลาสิ้นสุด');return}setBusy(true);setError('');try{await mutate(makeMutation('Room','room.create',{room,group,scheduleSlot}));setGroupId(groupIdNew);setMessage(`เพิ่ม ${name} แล้ว สามารถสลับไป Import รายชื่อได้ทันที`);setMode('import')}catch(cause){setError(cause instanceof Error?cause.message:'เพิ่มห้องไม่สำเร็จ')}finally{setBusy(false)}}
  return <Dialog title="จัดการห้องและรายชื่อนักเรียน" onClose={onClose}><div className="stack"><div className="segmented"><button type="button" className={mode==='import'?'active':''} onClick={()=>{setMode('import');setError('');setMessage('')}}>Import Excel</button><button type="button" className={mode==='room'?'active':''} onClick={()=>{setMode('room');setError('');setMessage('')}}>เพิ่มห้อง</button></div>{mode==='room'?<form className="stack" onSubmit={createRoom}><p className="muted">เพิ่มห้องและคาบสอนหลัก ห้องใหม่จะพร้อมใช้ในเช็กชื่อ งาน คะแนน และรายงานทันที</p><div className="field-row"><Field label="ระดับชั้น"><Select name="gradeLevelId" required>{data.gradeLevels.map((item)=><option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field><Field label="รหัสห้อง" helper="เช่น M4/3"><Input name="code" placeholder="M4/3" required autoFocus/></Field></div><Field label="ชื่อที่แสดง" helper="เช่น ม.4/3"><Input name="name" placeholder="ม.4/3" required/></Field><div className="field-row"><Field label="วันสอน"><Select name="weekday" defaultValue="1">{[1,2,3,4,5].map((day)=><option key={day} value={day}>วัน{weekdayNames[day]}</option>)}</Select></Field><Field label="คาบ"><Input name="period" type="number" min="1" max="20" defaultValue="1" required/></Field></div><div className="field-row"><Field label="เวลาเริ่ม"><Input name="startTime" type="time" defaultValue="08:30" required/></Field><Field label="เวลาสิ้นสุด"><Input name="endTime" type="time" defaultValue="09:20" required/></Field></div><Button type="submit" disabled={busy}><Plus/>{busy?'กำลังเพิ่ม…':'เพิ่มห้อง'}</Button></form>:<div className="stack"><p className="muted">เลือกห้องปลายทาง แล้วนำเข้ารายชื่อจากไฟล์ .xlsx ระบบจะอัปเดตคนเดิมจากรหัสนักเรียนและไม่ลบรายชื่อเดิม</p><Field label="ห้องปลายทาง"><Select value={groupId} onChange={(event)=>setGroupId(event.target.value)}>{data.gradeLevels.flatMap((grade)=>data.teachingGroups.filter((group)=>group.gradeLevelId===grade.id).map((group)=><option key={group.id} value={group.id}>{grade.name} · {group.name}</option>))}</Select></Field><div className="import-actions"><Button type="button" variant="secondary" onClick={()=>void downloadTemplate()}><DownloadSimple/>ดาวน์โหลดไฟล์ตัวอย่าง</Button><label className="button button-secondary file-button"><UploadSimple/>{busy?'กำลังอ่าน…':'เลือกไฟล์ .xlsx'}<input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onChange={(event)=>void readFile(event.target.files?.[0])}/></label></div><p className="helper">ควรตั้งคอลัมน์รหัสนักเรียนเป็น “ข้อความ” เพื่อรักษาเลข 0 ด้านหน้า</p>{fileName&&<div className="status-badge">{fileName}</div>}{preview.length>0&&<div className="import-preview"><div className="section-head"><strong>ตรวจพบ {preview.length} คน</strong><span className="status-badge success">พร้อมนำเข้า</span></div><div className="import-preview-list">{preview.slice(0,8).map((item)=><div className="import-preview-row" key={item.studentCode}><span>{item.number}</span><strong>{item.title}{item.firstName} {item.lastName}</strong><small>{item.studentCode} · {item.nickname||'ไม่มีชื่อเล่น'}</small></div>)}</div>{preview.length>8&&<p className="helper">และอีก {preview.length-8} คน</p>}</div>}<Button type="button" onClick={()=>void importStudents()} disabled={busy||!preview.length}><UploadSimple/>{busy?'กำลังนำเข้า…':`นำเข้า ${preview.length||''} คน`}</Button></div>}{error&&<div className="banner error" role="alert">{error}</div>}{message&&<div className="banner" role="status">{message}</div>}<div className="button-row end"><Button type="button" variant="ghost" onClick={onClose}>ปิด</Button></div></div></Dialog>
}

export function GradebookPage() {
  const { data, mutate, t } = useApp(); const [categoryDialog,setCategoryDialog]=useState(false); const [rosterDialog,setRosterDialog]=useState(false); const filter = useGroupFilter(); const roster = filter.group ? rosterForGroup(data, filter.group.id) : []; const assessmentIds = new Set(data.assessmentTargets.filter((item) => item.teachingGroupId === filter.groupId).map((item) => item.assessmentId)); const assessments = data.assessments.filter((item) => assessmentIds.has(item.id)); const rows = roster.map((student) => { const total = weightedTotal(student.id, assessments, data.assessmentCategories, data.scores); return { student, total, grade: gradeFor(total, data.gradeThresholds) } }); const dist = rows.reduce<Record<string,number>>((acc,row) => ({ ...acc, [row.grade]: (acc[row.grade] ?? 0) + 1 }), {})
  const lock = () => { if (!filter.group || !window.confirm('ล็อกผลเกรดห้องนี้หรือไม่? สามารถสร้างรายงานจากชุดคะแนนนี้ได้ทันที')) return; const now = new Date().toISOString(); const records: FinalGrade[] = rows.map(({ student,total,grade }) => ({ id: `${filter.groupId}:${student.id}`, version: 1, createdAt: now, updatedAt: now, teachingGroupId: filter.groupId, studentId: student.id, total, grade, lockedAt: now })); void mutate(makeMutation('FinalGrade','grades.lock',{ records })) }
  return <><PageHead title={t('gradebookTitle')} body={t('gradebookBody')}><div className="button-row"><Button variant="secondary" onClick={()=>setRosterDialog(true)}><UserPlus/>ห้องและนักเรียน</Button><Button variant="secondary" onClick={()=>setCategoryDialog(true)}>หมวดและเปอร์เซ็นต์</Button><Button onClick={lock}><LockKey />{t('lockGrades')}</Button></div></PageHead><GroupFilters filter={filter} /><div className="category-summary">{data.assessmentCategories.map((item)=><span className="status-badge" key={item.id}>{item.name} {item.weight}%</span>)}</div><section className="panel distribution"><h2>{t('gradeDistribution')}</h2><div className="distribution-bars">{data.gradeThresholds.map((threshold) => <div key={threshold.grade}><span>{threshold.grade}</span><div className="progress"><span style={{ width: `${rows.length ? (dist[threshold.grade] ?? 0) / rows.length * 100 : 0}%` }} /></div><strong>{dist[threshold.grade] ?? 0}</strong></div>)}</div></section><div className="table-wrap"><table className="data-table"><thead><tr><th>{t('number')}</th><th>{t('student')}</th>{data.assessmentCategories.map((item) => <th key={item.id}>{item.name}<br />{item.weight}%</th>)}<th>{t('total')}</th><th>{t('grade')}</th></tr></thead><tbody>{rows.map(({student,total,grade}) => <tr key={student.id}><td>{student.number}</td><td className="student-cell"><strong>{fullName(student)}</strong><span>{student.nickname} · {student.studentCode}</span></td>{data.assessmentCategories.map((category) => { const items = assessments.filter((item) => item.categoryId === category.id); const possible = items.reduce((sum,item) => sum + item.maxScore,0); const earned = items.reduce((sum,item) => sum + (data.scores.find((score) => score.assessmentId === item.id && score.studentId === student.id)?.value ?? 0),0); return <td key={category.id}>{possible ? (earned / possible * category.weight).toFixed(2) : '—'}</td> })}<td><strong>{total.toFixed(2)}</strong></td><td><span className="grade-chip">{grade}</span></td></tr>)}</tbody></table></div><div className="mobile-roster">{rows.map(({student,total,grade}) => <article className="student-card" key={student.id}><div className="student-card-head"><div><strong>{student.number}. {fullName(student)}</strong><div className="meta"><span>{student.nickname}</span><span>{student.studentCode}</span></div></div><span className="grade-chip">{grade}</span></div><strong>{total.toFixed(2)} คะแนน</strong></article>)}</div>{categoryDialog&&<CategoryManager onClose={()=>setCategoryDialog(false)}/>} {rosterDialog&&<RosterManager onClose={()=>setRosterDialog(false)}/>}</>
}

export function BehaviorPage() {
  const { data, mutate, t } = useApp(); const filter = useGroupFilter(); const roster = filter.group ? rosterForGroup(data, filter.group.id) : []; const [studentId,setStudentId] = useState(roster[0]?.id ?? ''); const [sentiment,setSentiment] = useState<BehaviorLog['sentiment']>('POSITIVE'); const [category,setCategory] = useState<BehaviorLog['category']>('LEARNING'); const [note,setNote] = useState('')
  const save = async (event: FormEvent) => { event.preventDefault(); if (!studentId || !filter.groupId || !note.trim()) return; const now = new Date().toISOString(); await mutate(makeMutation('BehaviorLog','behavior.create',{ id: crypto.randomUUID(), version: 1, createdAt: now, updatedAt: now, studentId, teachingGroupId: filter.groupId, occurredAt: now, sentiment, category, note: note.trim() })); setNote('') }
  const logs = data.behaviorLogs.filter((item) => item.teachingGroupId === filter.groupId).sort((a,b) => b.occurredAt.localeCompare(a.occurredAt)); return <><PageHead title={t('behaviorTitle')} body={t('behaviorBody')} /><GroupFilters filter={filter} /><div className="split-grid"><section className="panel"><h2>{t('addBehavior')}</h2><form className="stack" onSubmit={save}><Field label={t('student')}><Select value={studentId} onChange={(e) => setStudentId(e.target.value)}>{roster.map((item) => <option key={item.id} value={item.id}>{item.number}. {fullName(item)} ({item.nickname})</option>)}</Select></Field><div className="segmented"><button type="button" className={sentiment === 'POSITIVE' ? 'active' : ''} onClick={() => setSentiment('POSITIVE')}>{t('positive')}</button><button type="button" className={sentiment === 'FOLLOW_UP' ? 'active' : ''} onClick={() => setSentiment('FOLLOW_UP')}>{t('followUp')}</button></div><Field label={t('category')}><Select value={category} onChange={(e) => setCategory(e.target.value as BehaviorLog['category'])}><option value="LEARNING">การเรียน</option><option value="RESPONSIBILITY">ความรับผิดชอบ</option><option value="DISCIPLINE">วินัย</option><option value="HELPING">การช่วยเหลือ</option><option value="OTHER">อื่น ๆ</option></Select></Field><Field label={t('note')}><Textarea value={note} onChange={(e) => setNote(e.target.value)} required /></Field><Button type="submit"><UserPlus />{t('saveBehavior')}</Button></form></section><section className="panel"><h2>บันทึกล่าสุด</h2><div className="list">{logs.map((log) => { const student = data.students.find((item) => item.id === log.studentId); return <article className="behavior-item" key={log.id}><span className={`status-badge ${log.sentiment === 'POSITIVE' ? 'success' : 'warning'}`}>{log.sentiment === 'POSITIVE' ? t('positive') : t('followUp')}</span><strong>{student ? fullName(student) : '—'}</strong><p>{log.note}</p><small className="muted">{new Date(log.occurredAt).toLocaleString('th-TH')}</small></article> })}</div></section></div></>
}

export function ReportsPage() {
  const { data, demo, requestServerExport, t } = useApp(); const [scope,setScope] = useState('ROOM'); const [format,setFormat] = useState<'PDF'|'XLSX'>('PDF'); const [selected,setSelected] = useState<string[]>([data.teachingGroups[0]?.id].filter(Boolean)); const [busy,setBusy] = useState(false); const [message,setMessage] = useState('')
  const groups = useMemo(() => scope === 'ALL' ? data.teachingGroups : scope === 'GRADE' ? data.teachingGroups.filter((item) => item.gradeLevelId === data.teachingGroups.find((group) => group.id === selected[0])?.gradeLevelId) : data.teachingGroups.filter((item) => selected.includes(item.id)), [scope,selected,data.teachingGroups])
  const create = async () => { if (!groups.length) return; setBusy(true); setMessage(''); try { if (demo) { if (format === 'PDF') exportPdf(data,groups); else await exportExcel(data,groups); setMessage('สร้างไฟล์ตัวอย่างแล้ว') } else { const job = await requestServerExport({ format, scope, teachingGroupIds: groups.map((item) => item.id), includeBehavior: false }); setMessage(`รับงานแล้ว รหัส ${job.jobId} — ไฟล์จะปรากฏใน Google Drive`) } } catch (error) { setMessage(error instanceof Error ? error.message : 'สร้างรายงานไม่สำเร็จ') } finally { setBusy(false) } }
  const toggle = (id: string) => setSelected((value) => value.includes(id) ? value.filter((item) => item !== id) : scope === 'ROOM' ? [id] : [...value,id]); return <><PageHead title={t('reportsTitle')} body={t('reportsBody')} /><div className="split-grid"><section className="panel stack"><Field label={t('scope')}><Select value={scope} onChange={(e) => setScope(e.target.value)}><option value="ROOM">{t('oneRoom')}</option><option value="GRADE">{t('oneGrade')}</option><option value="SELECTED">{t('selectedRooms')}</option><option value="ALL">{t('allRooms')}</option></Select></Field>{scope !== 'ALL' && <fieldset className="target-grid"><legend>{t('targetRooms')}</legend>{data.teachingGroups.map((item) => <label className="checkbox-row" key={item.id}><input type={scope === 'ROOM' || scope === 'GRADE' ? 'radio' : 'checkbox'} checked={selected.includes(item.id)} onChange={() => toggle(item.id)} />{item.name}</label>)}</fieldset>}<Field label={t('format')}><Select value={format} onChange={(e) => setFormat(e.target.value as 'PDF'|'XLSX')}><option value="PDF">PDF สำหรับพิมพ์/ส่งต่อ</option><option value="XLSX">Excel (.xlsx)</option></Select></Field><Button onClick={() => void create()} disabled={busy || !groups.length}><DownloadSimple />{busy ? 'กำลังสร้าง…' : t('createReport')}</Button>{message && <div className="banner" role="status">{message}</div>}</section><section className="panel report-preview"><ChartBar size={42} /><h2>ตัวอย่างขอบเขต</h2><strong>{groups.length} ห้อง</strong><p className="muted">{groups.map((item) => item.name).join(' · ')}</p><p>PDF แยกหน้าตามห้อง ส่วน Excel แยกแท็บตามห้อง พร้อมรหัสนักเรียน ชื่อเล่น คะแนนรวม และเกรด</p></section></div></>
}

export function SettingsPage() {
  const { locale,theme,density,textSize,demo,online,syncSummary,setLocale,setTheme,setDensity,setTextSize,syncNow,lock,disconnect,navigate,updatePin,t } = useApp(); const queued = syncSummary.QUEUED + syncSummary.RETRY_WAIT + syncSummary.SENDING
  const [pinDialog,setPinDialog]=useState(false); const [currentPin,setCurrentPin]=useState(''); const [newPin,setNewPin]=useState(''); const [confirmPin,setConfirmPin]=useState(''); const [pinError,setPinError]=useState(''); const [pinBusy,setPinBusy]=useState(false)
  const savePin=async(event:FormEvent)=>{event.preventDefault();if(newPin!==confirmPin){setPinError('PIN ใหม่ไม่ตรงกัน');return}if(!/^\d{6,12}$/.test(newPin)){setPinError('PIN ใหม่ต้องเป็นตัวเลข 6–12 หลัก');return}setPinBusy(true);setPinError('');try{await updatePin(currentPin,newPin);setPinDialog(false);setCurrentPin('');setNewPin('');setConfirmPin('')}catch(cause){setPinError(cause instanceof Error?cause.message:'เปลี่ยน PIN ไม่สำเร็จ')}finally{setPinBusy(false)}}
  return <><PageHead title={t('settingsTitle')} body="ปรับหน้าจอ ความปลอดภัย และตรวจสถานะข้อมูล" /><div className="panel-grid"><section className="panel stack"><h2>{t('appearance')}</h2><Field label={t('theme')}><Select value={theme} onChange={(e) => setTheme(e.target.value as typeof theme)}><option value="system">{t('system')}</option><option value="light">{t('light')}</option><option value="dark">{t('dark')}</option><option value="contrast">{t('contrast')}</option></Select></Field><Field label={t('language')}><Select value={locale} onChange={(e) => setLocale(e.target.value as typeof locale)}><option value="th">{t('thai')}</option><option value="en">{t('english')}</option></Select></Field><Field label={t('density')}><Select value={density} onChange={(e) => setDensity(e.target.value as typeof density)}><option value="comfortable">{t('comfortable')}</option><option value="compact">{t('compact')}</option></Select></Field><label className="checkbox-row"><input type="checkbox" checked={textSize === 'large'} onChange={(e) => setTextSize(e.target.checked ? 'large' : 'standard')} />ตัวอักษรขนาดใหญ่</label></section><section className="panel stack"><h2>{t('connection')}</h2><div className="list-row"><div><strong>{demo ? t('demo') : online ? t('connected') : t('offline')}</strong><div className="meta"><span>{queued} {t('queuedChanges')}</span><span>{syncSummary.CONFLICT} {t('conflicts')}</span></div></div><span className={`status-badge ${online ? 'success' : 'warning'}`}>{online ? t('online') : t('offline')}</span></div><Button variant="secondary" onClick={() => void syncNow()} disabled={demo || !online}>{t('syncNow')}</Button><Button variant="secondary" onClick={() => setPinDialog(true)} disabled={demo}>เปลี่ยน PIN</Button><Button variant="secondary" onClick={() => navigate('behavior')}>{t('behavior')}</Button><Button variant="secondary" onClick={() => navigate('reports')}>{t('reports')}</Button><Button variant="secondary" onClick={lock}>{t('signOut')}</Button><Button variant="danger" onClick={() => { if (window.confirm('ตัดการเชื่อมต่อและลบข้อมูลออฟไลน์ที่เข้ารหัสจากเครื่องนี้หรือไม่?')) disconnect() }}>ตัดการเชื่อมต่ออุปกรณ์นี้</Button></section></div>{pinDialog&&<Dialog title="เปลี่ยน PIN" onClose={()=>setPinDialog(false)}><form className="stack" onSubmit={savePin}><Field label="PIN ปัจจุบัน"><Input type="password" inputMode="numeric" value={currentPin} onChange={(e)=>setCurrentPin(e.target.value.replace(/\D/g,'').slice(0,12))} required /></Field><Field label="PIN ใหม่ 6–12 หลัก"><Input type="password" inputMode="numeric" value={newPin} onChange={(e)=>setNewPin(e.target.value.replace(/\D/g,'').slice(0,12))} required /></Field><Field label="ยืนยัน PIN ใหม่" error={pinError}><Input type="password" inputMode="numeric" value={confirmPin} onChange={(e)=>setConfirmPin(e.target.value.replace(/\D/g,'').slice(0,12))} required /></Field><div className="button-row end"><Button type="button" variant="ghost" onClick={()=>setPinDialog(false)}>{t('cancel')}</Button><Button type="submit" disabled={pinBusy}>{pinBusy?'กำลังเปลี่ยน…':'เปลี่ยน PIN'}</Button></div></form></Dialog>}</>
}
